let package = Package(
    name: "FigCraftKit",
    platforms: [.iOS("26.0")],
    products: [
        .library(name: "FigCraftKit", targets: ["FigCraftKit"]),
    ],
    targets: [
        .binaryTarget(name: "FigCraftBridge", path: "FigCraftBridge.xcframework"),
        .target(
            name: "FigCraftKit",
            dependencies: ["FigCraftBridge"],
            swiftSettings: [.swiftLanguageMode(.v5)],  // UniFFI-generated code is not Swift 6 strict-concurrency clean
