            linkerSettings: [
                .linkedFramework("Foundation"), .linkedFramework("CoreFoundation"), .linkedFramework("Security"),
                .linkedFramework("SystemConfiguration"), .linkedLibrary("c++"),
            ]
        ),
    ]
